        pool.execute(move || {
            let mut num = counter_clone.lock().unwrap();
            *num += 1;
        });
    }

    drop(pool); // Blocks until all 20 jobs complete
    assert_eq!(*counter.lock().unwrap(), 20);

    println!("RUST SFT 0004: ThreadPool cleanly executed and joined all workers.");
}

